  "inlineSchema": "// Prisma schema — Calendar Comparison App\n// See CLAUDE.md for the full data model rationale and conventions.\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// ---------------------------------------------------------------------------\n// Auth (NextAuth.js — OAuth). Standard NextAuth Prisma adapter shape.\n// ---------------------------------------------------------------------------\n\nmodel User {\n  id            String    @id @default(cuid())\n  name          String?\n  email         String?   @unique\n  emailVerified DateTime?\n  image         String?\n\n  accounts Account[]\n  sessions Session[]\n\n  projectGroups  ProjectGroup[]\n  projects       Project[]\n  calendarBlocks CalendarBlock[]\n  templates      Template[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel Account {\n  id                String  @id @default(cuid())\n  userId            String\n  type              String\n  provider          String\n  providerAccountId String\n  refresh_token     String? @db.Text\n  access_token      String? @db.Text\n  expires_at        Int?\n  token_type        String?\n  scope             String?\n  id_token          String? @db.Text\n  session_state     String?\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([provider, providerAccountId])\n}\n\nmodel Session {\n  id           String   @id @default(cuid())\n  sessionToken String   @unique\n  userId       String\n  expires      DateTime\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n\nmodel VerificationToken {\n  identifier String\n  token      String   @unique\n  expires    DateTime\n\n  @@unique([identifier, token])\n}\n\n// ---------------------------------------------------------------------------\n// Domain model\n// ---------------------------------------------------------------------------\n\n// The \"color\" level. Every bubble's fill color is resolved through\n// Project -> ProjectGroup.color — never stored directly on Project or\n// CalendarBlock. See CLAUDE.md \"Rule: a block's color is always derived...\".\nmodel ProjectGroup {\n  id     String @id @default(cuid())\n  userId String\n  name   String\n  color  String // hex, e.g. \"#4F46E5\"\n\n  user     User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  projects Project[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([userId, name])\n  @@index([userId])\n}\n\n// The \"bubble\" level. One Project = one distinct bubble identity; its color\n// comes from its ProjectGroup.\nmodel Project {\n  id      String @id @default(cuid())\n  userId  String\n  groupId String\n  name    String\n\n  user  User         @relation(fields: [userId], references: [id], onDelete: Cascade)\n  group ProjectGroup @relation(fields: [groupId], references: [id], onDelete: Cascade)\n\n  calendarBlocks CalendarBlock[]\n  templateBlocks TemplateBlock[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([userId, name])\n  @@index([userId])\n  @@index([groupId])\n}\n\n// Atomic 30-min storage unit. Bubbles are computed at render time by merging\n// consecutive same-project CalendarBlocks within a day — never persisted.\n// See CLAUDE.md \"Rule: bubbles are a display-layer merge, never stored.\"\nmodel CalendarBlock {\n  id          String      @id @default(cuid())\n  userId      String\n  projectId   String\n  weekId      String // ISO week, e.g. \"2026-W29\" (Monday-start)\n  dayOfWeek   Int // 0 (Mon) – 6 (Sun)\n  slotIndex   Int // 0–47, 30-min increments from midnight\n  createdFrom CreatedFrom @default(MANUAL)\n\n  user    User    @relation(fields: [userId], references: [id], onDelete: Cascade)\n  project Project @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // One project occupies at most one slot per day per week — prevents\n  // overlapping blocks and keeps the bubble-merge scan well-defined.\n  @@unique([userId, weekId, dayOfWeek, slotIndex])\n  @@index([userId, weekId])\n  @@index([projectId])\n}\n\nenum CreatedFrom {\n  TEMPLATE\n  MANUAL\n}\n\n// A user's reusable default week. TemplateBlocks are copied into real\n// CalendarBlock rows (createdFrom: TEMPLATE) when a fresh week is opened —\n// never referenced live. See CLAUDE.md \"Templates are read-only at\n// instantiation time.\"\nmodel Template {\n  id        String  @id @default(cuid())\n  userId    String\n  name      String\n  isDefault Boolean @default(false)\n\n  user   User            @relation(fields: [userId], references: [id], onDelete: Cascade)\n  blocks TemplateBlock[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n  // Enforced in application code (Postgres can't do a partial unique index\n  // via Prisma syntax directly): only one Template per user may have\n  // isDefault = true. Wrap default-swap in a transaction — unset the old\n  // default, then set the new one.\n\n  @@unique([userId, name])\n  @@index([userId])\n}\n\nmodel TemplateBlock {\n  id         String @id @default(cuid())\n  templateId String\n  projectId  String\n  dayOfWeek  Int // 0 (Mon) – 6 (Sun)\n  slotIndex  Int // 0–47\n\n  template Template @relation(fields: [templateId], references: [id], onDelete: Cascade)\n  project  Project  @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  @@unique([templateId, dayOfWeek, slotIndex])\n  @@index([templateId])\n}\n",
